mapper.sql:
i.state = 'open' AND r.enabled = 1
AND i.visibility_status IN ('LEGACY_VISIBLE', 'PUBLIC')
AND i.difficulty = #{difficulty}
AND i.participation_status = #{participationStatus}

    AND (r.tech_stack LIKE CONCAT('%', #{tech}, '%') OR r.primary_language = #{tech}
         OR i.labels_json LIKE CONCAT('%', #{tech}, '%'))


    AND (i.title_zh LIKE CONCAT('%', #{keyword}, '%')
         OR i.title_original LIKE CONCAT('%', #{keyword}, '%')
         OR i.summary_zh LIKE CONCAT('%', #{keyword}, '%'))

AND i.github_updated_at >= DATE_SUB(NOW(), INTERVAL #{updatedDays} DAY)

mapper.select:
SELECT 
FROM open_source_issue i JOIN open_source_repository r ON r.id = i.repository_id
WHERE 1 = 1

    AND (i.title_original LIKE CONCAT('%', #{keyword}, '%')
         OR i.title_zh LIKE CONCAT('%', #{keyword}, '%')
         OR r.full_name LIKE CONCAT('%', #{keyword}, '%'))

AND i.published = #{published}
AND i.translation_status = #{translationStatus}
ORDER BY i.github_updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM open_source_issue i JOIN open_source_repository r ON r.id = i.repository_id WHERE 1 = 1
AND (i.title_original LIKE CONCAT('%', #{keyword}, '%') OR i.title_zh LIKE CONCAT('%', #{keyword}, '%') OR r.full_name LIKE CONCAT('%', #{keyword}, '%'))
AND i.published = #{published} AND i.translation_status = #{translationStatus}
